/* Layout for this component's own nodes.
   These were per-node `styles` overrides. Past a certain number of them in
   one document the browser stops matching the compiled
   [data-bz-node="x"][data-bz-node] rules — some apply and some silently do
   not — so the same declarations live here instead, where they hold. See the
   note in the commit message; this is a platform bug worth fixing upstream.
   ------------------------------------------------------------------------- */
[data-bz-node="hero"]{padding-top:160px;padding-bottom:136px;padding-left:48px;padding-right:48px;position:relative;overflow:hidden}
[data-bz-node="hero-photo-row"]{position:absolute;inset:0px;z-index:0}
[data-bz-node="hero-photo-col"]{height:100%}
[data-bz-node="hero-inner"]{max-width:1280px;margin-left:auto;margin-right:auto;position:relative;z-index:2}
[data-bz-node="hero-brands-row"]{display:flex;justify-content:center;align-items:center;flex-wrap:wrap;gap:36px}
@media (max-width: 640px){
[data-bz-node="hero"]{padding-top:96px;padding-bottom:56px;padding-left:20px;padding-right:20px}
}

/* The photograph, its scrim and the copy are three layers, exactly as the
   handoff has them — the scrim is drawn rather than being a node of its own so
   the copy stays the only thing in the tree a dealer can select. */
[data-bz-node="hero"] { text-align: center; }
/* The photograph fills the band; the scrim below sits over it, the copy over both. */
[data-bz-node="hero-photo-row"], [data-bz-node="hero-photo-row"] .bz-col,
[data-bz-node="hero-photo"], [data-bz-node="hero-photo"] .bz-container,
[data-bz-node="hero-photo"] figure { height: 100%; }
[data-bz-node="hero-photo"] img { width: 100%; height: 100%; object-fit: cover; object-position: center; }
[data-bz-node="hero"]::before {
  content: "";
  position: absolute;
  inset: 0;
  background: rgba(20, 20, 20, 0.68);
  z-index: 1;
}
[data-bz-node="hero"] .bz-block { padding-block: 0; }

.bz-block[data-bz-node="hero-heading"] p.bz-eyebrow { color: #E2E2E2; margin: 0 0 18px; }
[data-bz-node="hero-heading"] h1 { max-width: 900px; margin: 0 auto 26px; color: #fff; }

[data-bz-node="hero-brandmark"] img {
  display: block;
  width: 82%;
  max-width: 1400px;
  margin: 0 auto 44px;
  pointer-events: none;
}

/* Two selects and a CTA. The Category list is filtered from Type by the
   platform's dependentselect behaviour (the options carry data-bz-when); the
   component's own script only has to turn a submit into a navigation, which no
   behaviour does. */
.ss-hero-search {
  display: flex;
  gap: 12px;
  max-width: 520px;
  margin: 0 auto 56px;
}
.ss-hero-search label { flex: 1; margin: 0 6px; }
.ss-field {
  width: 100%;
  min-height: 46px;
  padding: 0 12px;
  background: var(--paper);
  border: 1.5px solid var(--line);
  border-radius: var(--radius-input);
  font-family: var(--font-body);
  font-size: var(--text-small);
  color: #242424;
  appearance: none;
}
.ss-field:disabled { opacity: 1; color: #242424; background: var(--paper); }
.ss-hero-search .bz-btn { white-space: nowrap; }
.ss-visually-hidden {
  position: absolute; width: 1px; height: 1px;
  padding: 0; margin: -1px; overflow: hidden;
  clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0;
}

/* Brand shortcuts */
[data-bz-node="hero-brands-row"] { font: 700 12px / 1 var(--font-body); letter-spacing: 0.1em; }
[data-bz-node="hero-brands-row"] .bz-col { padding: 0; }
[data-bz-node="hero-brands-row"] .bz-block--text p {
  margin: 0;
  font: 700 12px / 1 var(--font-body);
  letter-spacing: 0.1em;
}
[data-bz-node="hero-brands-row"] a {
  display: inline-block;
  padding: 4px 0;
  color: #B5B5B5;
  font: inherit;
  letter-spacing: inherit;
  text-decoration: none;
}
[data-bz-node="hero-brands-row"] a:hover { color: #fff; text-decoration: none; }

@media (max-width: 1100px) {
  [data-bz-node="hero-heading"] h1 { font-size: 46px; }
}
@media (max-width: 640px) {
  [data-bz-node="hero-heading"] h1 { font-size: 30px; }
  [data-bz-node="hero-brandmark"] img { width: 92%; margin-bottom: 32px; }
  .ss-hero-search { flex-direction: column; max-width: 320px; gap: 12px; margin-bottom: 40px; }
  .ss-hero-search label { margin: 0; }
  [data-bz-node="hero-brands-row"] { gap: 16px 22px; }
}

