/* Turn the hero's Type + Category choice into an inventory search.

   The dependent Category list is the platform's `dependentselect` behaviour —
   this only adds the one thing a behaviour cannot do, which is navigate. */
(function () {
  var root = document.querySelector('[data-bz-node="hero-search"]');
  if (!root) return;

  var button = root.querySelector('[data-ss-search]');
  var type = root.querySelector('[data-ss-type]');
  var category = root.querySelector('[data-ss-category]');
  if (!button || !type || !category) return;

  function go() {
    var base = button.getAttribute('data-ss-url') || '/store/inventory';
    var params = [];
    if (type.value) params.push('type=' + encodeURIComponent(type.value));
    if (category.value) params.push('category=' + encodeURIComponent(category.value));
    window.location.href = params.length
      ? base + (base.indexOf('?') > -1 ? '&' : '?') + params.join('&')
      : base;
  }

  button.addEventListener('click', go);
  root.addEventListener('keydown', function (event) {
    if (event.key === 'Enter') { event.preventDefault(); go(); }
  });
})();
